"use client";

import { useCallback, useEffect, useRef } from "react";
import { useSwipe } from "../interaction/hooks";
import { cx } from "../utils/cx";
import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from "../icons/interface";

export type LightboxItem = {
  src: string;
  alt: string;
  caption?: string;
  width?: number;
  height?: number;
};

export type LightboxProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: LightboxItem[];
  index: number;
  onIndexChange: (index: number) => void;
  /** Accessible name of the viewer. */
  label?: string;
  /** Wrap from the last photograph to the first. Default false. */
  loop?: boolean;
  className?: string;
};

/**
 * A full-screen viewer on the native <dialog> (top layer, focus trap, Escape, focus return). Left/Right and
 * swipe move between photographs, Home/End jump, the neighbors are preloaded, and the counter is a live region.
 * Controlled: the host owns `open` and `index`.
 */
export function Lightbox({
  open,
  onOpenChange,
  items,
  index,
  onIndexChange,
  label = "Photographs",
  loop,
  className,
}: LightboxProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const stage = useRef<HTMLDivElement>(null);
  const last = items.length - 1;
  const previous = useRef(index);
  const direction = index > previous.current ? "next" : index < previous.current ? "prev" : "none";
  useEffect(() => {
    previous.current = index;
  }, [index]);
  const item = items[index];

  const go = useCallback(
    (to: number) => {
      if (!items.length) return;
      const next = to < 0 ? (loop ? last : 0) : to > last ? (loop ? 0 : last) : to;
      if (next !== index) onIndexChange(next);
    },
    [items.length, last, loop, index, onIndexChange],
  );

  useEffect(() => {
    const el = dialog.current;
    if (!el) return;
    if (open && !el.open) el.showModal();
    else if (!open && el.open) el.close();
  }, [open]);

  // on the document, so keys still work after a button that had focus becomes unavailable
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight") go(index + 1);
      else if (e.key === "ArrowLeft") go(index - 1);
      else if (e.key === "Home") go(0);
      else if (e.key === "End") go(last);
      else return;
      e.preventDefault();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, go, index, last]);

  useSwipe(stage, { onSwipe: (d) => (d === "left" ? go(index + 1) : d === "right" ? go(index - 1) : undefined) }, [
    go,
    index,
    open,
  ]);

  useEffect(() => {
    if (!open) return;
    for (const i of [index - 1, index + 1]) {
      const n = items[i];
      if (n) new window.Image().src = n.src;
    }
  }, [open, index, items]);

  const atStart = !loop && index <= 0;
  const atEnd = !loop && index >= last;
  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: the click only dismisses; Escape already closes a native dialog
    <dialog
      ref={dialog}
      aria-label={label}
      className={cx("hm-lightbox", className)}
      onClose={() => onOpenChange(false)}
      onClick={(e) => {
        // a click on the dialog itself or the bare stage (not the image, buttons or caption) dismisses
        if (e.target === e.currentTarget || e.target === stage.current) onOpenChange(false);
      }}
    >
      {open && item ? (
        <>
          <header className="hm-lightbox-bar">
            <p className="hm-lightbox-count" aria-live="polite" aria-atomic="true">
              {index + 1} / {items.length}
            </p>
            <button type="button" className="hm-lightbox-button" aria-label="Close" onClick={() => onOpenChange(false)}>
              <CloseIcon size={16} />
            </button>
          </header>
          <div ref={stage} className="hm-lightbox-stage">
            <img
              key={item.src}
              data-direction={direction}
              className="hm-lightbox-img"
              src={item.src}
              alt={item.alt}
              width={item.width}
              height={item.height}
              draggable={false}
            />
          </div>
          {item.caption ? <p className="hm-lightbox-caption">{item.caption}</p> : null}
          <button
            type="button"
            className="hm-lightbox-button hm-lightbox-prev"
            aria-label="Previous photograph"
            aria-disabled={atStart || undefined}
            onClick={() => go(index - 1)}
          >
            <ChevronLeftIcon size={16} />
          </button>
          <button
            type="button"
            className="hm-lightbox-button hm-lightbox-next"
            aria-label="Next photograph"
            aria-disabled={atEnd || undefined}
            onClick={() => go(index + 1)}
          >
            <ChevronRightIcon size={16} />
          </button>
        </>
      ) : null}
    </dialog>
  );
}
